import { LLMClient, LLMResponse, LLMOptions } from '../src/llm-client.js';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Simulate an SDK error with an optional HTTP status code. */
function makeApiError(status: number | undefined, message: string): Error & { status?: number } {
  const err = new Error(message) as Error & { status?: number };
  if (status !== undefined) err.status = status;
  return err;
}

/** Build a fake SDK Message response (the shape client.messages.create returns). */
function makeFakeMessage(overrides: Record<string, unknown> = {}) {
  return {
    id: 'msg_mock_001',
    type: 'message',
    role: 'assistant',
    content: [{ type: 'text', text: 'Hello, world!' }],
    model: 'claude-sonnet-4-20250514',
    usage: { input_tokens: 10, output_tokens: 25 },
    ...overrides,
  };
}

// ---------------------------------------------------------------------------
// Suite
// ---------------------------------------------------------------------------

describe('LLMClient', () => {
  let mockCreate: jest.Mock;
  let mockMessages: { create: jest.Mock };
  let mockAnthropic: { messages: { create: jest.Mock } };

  beforeEach(() => {
    mockCreate = jest.fn();
    mockMessages = { create: mockCreate };
    mockAnthropic = { messages: mockMessages };
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  // -----------------------------------------------------------------------
  // send() – success path
  // -----------------------------------------------------------------------

  describe('send()', () => {
    test('returns LLMResponse on success', async () => {
      mockCreate.mockResolvedValue(makeFakeMessage());

      const client = new LLMClient({ anthropic: mockAnthropic as never, maxRetries: 0 });
      const result = await client.send('test prompt');

      expect(result).toMatchObject({
        content: 'Hello, world!',
        model: 'claude-sonnet-4-20250514',
        usage: { inputTokens: 10, outputTokens: 25 },
      });
      expect(typeof result.durationMs).toBe('number');
      expect(result.durationMs).toBeGreaterThanOrEqual(0);
      expect(mockCreate).toHaveBeenCalledTimes(1);
      expect(mockCreate).toHaveBeenCalledWith(
        expect.objectContaining({
          model: expect.any(String),
          max_tokens: expect.any(Number),
          messages: expect.arrayContaining([
            expect.objectContaining({ role: 'user', content: 'test prompt' }),
          ]),
        }),
      );
    });

    // -----------------------------------------------------------------------
    // Retry-able errors
    // -----------------------------------------------------------------------

    test('retries on network timeout (status undefined)', async () => {
      const timeoutErr = makeApiError(undefined, 'Connection timeout');
      mockCreate
        .mockRejectedValueOnce(timeoutErr)
        .mockRejectedValueOnce(timeoutErr)
        .mockResolvedValueOnce(makeFakeMessage());

      jest.useFakeTimers();
      const client = new LLMClient({ anthropic: mockAnthropic as never, maxRetries: 3, baseDelayMs: 1000 });

      const promise = client.send('retry-me');
      await jest.advanceTimersByTimeAsync(1000); // after attempt 0
      await jest.advanceTimersByTimeAsync(2000); // after attempt 1

      const result = await promise;
      expect(result.content).toBe('Hello, world!');
      expect(mockCreate).toHaveBeenCalledTimes(3);
    });

    test('retries on HTTP 429', async () => {
      const rateErr = makeApiError(429, 'Rate limited');
      mockCreate
        .mockRejectedValueOnce(rateErr)
        .mockRejectedValueOnce(rateErr)
        .mockResolvedValueOnce(makeFakeMessage());

      jest.useFakeTimers();
      const client = new LLMClient({ anthropic: mockAnthropic as never, maxRetries: 3, baseDelayMs: 1000 });

      const promise = client.send('test');
      await jest.advanceTimersByTimeAsync(1000);
      await jest.advanceTimersByTimeAsync(2000);

      const result = await promise;
      expect(result.content).toBe('Hello, world!');
      expect(mockCreate).toHaveBeenCalledTimes(3);
    });

    test('retries on HTTP 5xx', async () => {
      const serverErr = makeApiError(502, 'Bad gateway');
      mockCreate
        .mockRejectedValueOnce(serverErr)
        .mockRejectedValueOnce(serverErr)
        .mockResolvedValueOnce(makeFakeMessage());

      jest.useFakeTimers();
      const client = new LLMClient({ anthropic: mockAnthropic as never, maxRetries: 3, baseDelayMs: 1000 });

      const promise = client.send('test');
      await jest.advanceTimersByTimeAsync(1000);
      await jest.advanceTimersByTimeAsync(2000);

      const result = await promise;
      expect(result.content).toBe('Hello, world!');
      expect(mockCreate).toHaveBeenCalledTimes(3);
    });

    // -----------------------------------------------------------------------
    // Non-retry-able errors
    // -----------------------------------------------------------------------

    test.each([
      [401, 'Unauthorized'],
      [403, 'Forbidden'],
      [400, 'Bad request'],
    ])('does NOT retry HTTP %s (%s)', async (status, msg) => {
      const err = makeApiError(status, msg);
      mockCreate.mockRejectedValue(err);

      const client = new LLMClient({ anthropic: mockAnthropic as never, maxRetries: 3, baseDelayMs: 10 });
      await expect(client.send('test')).rejects.toThrow(msg);
      expect(mockCreate).toHaveBeenCalledTimes(1);
    });

    // -----------------------------------------------------------------------
    // Retry exhaustion
    // -----------------------------------------------------------------------

    test('throws after exhausting all retries', async () => {
      const err = makeApiError(429, 'Always rate limited');
      mockCreate.mockRejectedValue(err);

      jest.useFakeTimers();
      const client = new LLMClient({ anthropic: mockAnthropic as never, maxRetries: 2, baseDelayMs: 100 });

      const rejection = expect(client.send('test')).rejects.toThrow('Always rate limited');
      await jest.advanceTimersByTimeAsync(100);  // attempt 0 → attempt 1
      await jest.advanceTimersByTimeAsync(200);  // attempt 1 → attempt 2
      // attempt 2 fails → no more retries (2 < 2 is false)
      await rejection;

      // total calls = maxRetries + 1 = 3
      expect(mockCreate).toHaveBeenCalledTimes(3);
    });

    // -----------------------------------------------------------------------
    // Duration tracking
    // -----------------------------------------------------------------------

    test('records durationMs', async () => {
      mockCreate.mockImplementation(async () => {
        await new Promise((r) => setTimeout(r, 50));
        return makeFakeMessage();
      });

      jest.useFakeTimers();
      const client = new LLMClient({ anthropic: mockAnthropic as never, maxRetries: 0 });

      const promise = client.send('test');
      await jest.advanceTimersByTimeAsync(50);
      const result = await promise;

      expect(result.durationMs).toBeGreaterThanOrEqual(50);
    });

    // -----------------------------------------------------------------------
    // Custom options passthrough
    // -----------------------------------------------------------------------

    test('passes custom model and maxTokens to the SDK', async () => {
      mockCreate.mockResolvedValue(makeFakeMessage({ model: 'clopus-4-5' }));

      const client = new LLMClient({ anthropic: mockAnthropic as never, maxRetries: 0 });
      await client.send('hello', { model: 'clopus-4-5', maxTokens: 2048, temperature: 0.5 });

      expect(mockCreate).toHaveBeenCalledWith(
        expect.objectContaining({
          model: 'clopus-4-5',
          max_tokens: 2048,
          temperature: 0.5,
        }),
      );
    });
  });

  // -----------------------------------------------------------------------
  // createMock()
  // -----------------------------------------------------------------------

  describe('createMock()', () => {
    test('returns a mock instance that returns the stub response on success', async () => {
      const stub: LLMResponse = {
        content: 'Mock reply',
        model: 'mock-model',
        usage: { inputTokens: 5, outputTokens: 9 },
        durationMs: 0,
      };

      const client = LLMClient.createMock(stub);
      const result = await client.send('anything');

      expect(result.content).toBe('Mock reply');
      expect(result.model).toBe('mock-model');
      expect(result.usage).toEqual({ inputTokens: 5, outputTokens: 9 });
      expect(result.durationMs).toBeGreaterThanOrEqual(0);
    });

    test('returns a mock instance that throws when given an Error', async () => {
      const err = new Error('Simulated failure');
      const client = LLMClient.createMock(err);

      await expect(client.send('test')).rejects.toThrow('Simulated failure');
    });

    test('createMock instance supports retry simulation', async () => {
      // createMock with an error; verify that the default retry logic kicks in
      // by checking that the error is still thrown after exhaustion
      const err = makeApiError(429, 'Mock rate-limit');
      const client = LLMClient.createMock(err);

      // Should not hang — retries should exhaust and rethrow
      await expect(client.send('test')).rejects.toThrow('Mock rate-limit');
    });
  });
});

import Anthropic from '@anthropic-ai/sdk';
import type { Message, MessageCreateParamsNonStreaming } from '@anthropic-ai/sdk/resources/messages/messages.js';

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export interface LLMOptions {
  model?: string;
  maxTokens?: number;
  temperature?: number;
  timeout?: number;
}

export interface LLMResponse {
  content: string;
  model: string;
  usage: {
    inputTokens: number;
    outputTokens: number;
  };
  durationMs: number;
}

export interface LLMClientConfig {
  maxRetries?: number;   // default 3
  baseDelayMs?: number;  // default 1000
  apiKey?: string;       // default process.env.ANTHROPIC_API_KEY
}

// ---------------------------------------------------------------------------
// Client
// ---------------------------------------------------------------------------

const DEFAULT_MODEL = 'claude-sonnet-4-20250514';
const DEFAULT_MAX_TOKENS = 1024;

export class LLMClient {
  private readonly anthropic: Anthropic;
  private readonly maxRetries: number;
  private readonly baseDelayMs: number;

  /**
   * @param config         Public config options.
   * @param config.anthropic  Optional pre-configured Anthropic SDK instance
   *                          (used for dependency injection / testing).
   */
  constructor(
    config?: LLMClientConfig & { anthropic?: Anthropic },
  ) {
    this.maxRetries = config?.maxRetries ?? 3;
    this.baseDelayMs = config?.baseDelayMs ?? 1000;

    if (config?.anthropic) {
      this.anthropic = config.anthropic;
    } else {
      this.anthropic = new Anthropic({
        apiKey: config?.apiKey ?? process.env.ANTHROPIC_API_KEY,
      });
    }
  }

  // -----------------------------------------------------------------------
  // Public API
  // -----------------------------------------------------------------------

  /**
   * Send a prompt to the LLM and receive a structured response.
   * Automatically retries on retry-able errors (network timeout, 429, 5xx).
   */
  async send(prompt: string, options?: LLMOptions): Promise<LLMResponse> {
    const startTime = Date.now();

    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
      try {
        const body: MessageCreateParamsNonStreaming = {
          model: options?.model ?? DEFAULT_MODEL,
          max_tokens: options?.maxTokens ?? DEFAULT_MAX_TOKENS,
          messages: [{ role: 'user', content: prompt }],
        };
        if (options?.temperature !== undefined) {
          (body as Record<string, unknown>).temperature = options.temperature;
        }

        const response = await this.anthropic.messages.create(body, {
          timeout: options?.timeout,
        });

        const durationMs = Date.now() - startTime;
        const content = (response.content as Array<{ type: string; text?: string }>)
          .filter((b) => b.type === 'text')
          .map((b) => b.text ?? '')
          .join('');

        return {
          content,
          model: response.model,
          usage: {
            inputTokens: response.usage.input_tokens,
            outputTokens: response.usage.output_tokens,
          },
          durationMs,
        };
      } catch (err: unknown) {
        // If this is the last attempt, rethrow immediately.
        if (attempt >= this.maxRetries || !this.isRetryable(err)) {
          throw err;
        }

        const delayMs = this.baseDelayMs * Math.pow(2, attempt);
        console.log(
          `[WARN] LLM call failed (attempt ${attempt + 1}/${this.maxRetries + 1}), retrying in ${delayMs}ms: ${(err as Error).message}`,
        );
        await this.sleep(delayMs);
      }
    }

    // Unreachable -- the loop always returns or throws.
    throw new Error('Unexpected state in LLMClient.send');
  }

  // -----------------------------------------------------------------------
  // Static factory
  // -----------------------------------------------------------------------

  /**
   * Create a mock LLMClient that does **not** make real API calls.
   *
   * @param stubResponse  Return this LLMResponse on success, or throw this
   *                      Error on failure.  The full retry machinery is still
   *                      active so you can test retry exhaustion.
   */
  static createMock(stubResponse: LLMResponse | Error): LLMClient {
    const mockAnthropic = {
      messages: {
        create: async (): Promise<Message> => {
          if (stubResponse instanceof Error) {
            throw stubResponse;
          }
          return {
            id: 'mock_msg_id',
            type: 'message',
            role: 'assistant',
            content: [{ type: 'text', text: stubResponse.content }],
            model: stubResponse.model,
            usage: {
              input_tokens: stubResponse.usage.inputTokens,
              output_tokens: stubResponse.usage.outputTokens,
            },
          } as Message;
        },
      },
    };

    return new LLMClient({ anthropic: mockAnthropic as unknown as Anthropic });
  }

  // -----------------------------------------------------------------------
  // Private helpers
  // -----------------------------------------------------------------------

  /**
   * Determine whether an error is worth retrying.
   *
   * Retry-able:
   *   - Network / connection errors  (status === undefined)
   *   - HTTP 429 (rate-limit)
   *   - HTTP 5xx (server errors)
   *
   * Non-retry-able (thrown immediately):
   *   - HTTP 401 (auth)
   *   - HTTP 403 (permission)
   *   - HTTP 400 (bad request)
   */
  private isRetryable(err: unknown): boolean {
    const error = err as { status?: number };
    const status = error.status;

    // Non-retry-able status codes
    if (status === 401 || status === 403 || status === 400) {
      return false;
    }

    // Retry-able: rate limits, server errors, network timeouts
    if (status === 429) return true;
    if (status !== undefined && status >= 500) return true;
    if (status === undefined) return true; // e.g. APIConnectionTimeoutError

    return false;
  }

  /** Promise-based delay for retry back-off. */
  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

